-- ============================================================
--  013_relacionadas_cno_carga
--
--  Carga las ocupaciones relacionadas CNO desde el catálogo oficial
--  "2CNO_2024_(2025-06-13).xlsx", hoja «Relacionadas - C.N.O.».
--
--  Por qué: `cno_relacionadas` tenía UNA fila (y de una copia de análisis, con
--  datos de prueba). El catálogo trae 1.716 relaciones para las ocupaciones
--  originales. Comparativa y Validación Experta mostraban "Sin ocupaciones
--  relacionadas" para todo.
--
--  Mismo esquema que la 012: originales desde el Excel, y propagación a las
--  copias ya existentes desde su ocupación base. Idempotente por el par
--  (ocupación, relacionada). Solo la FK a `cno_ocupacion` aplica aquí:
--  `codigo_ocupacion` (la relacionada) es texto libre en la tabla.
--
--  NO lleva BEGIN/COMMIT: el runner envuelve cada archivo en su transacción.
-- ============================================================

CREATE TEMP TABLE tmp_rel_cno (cod_ocupacion text, nombre_ocupacion text, cod_rel text, nombre_rel text, PRIMARY KEY (cod_ocupacion, cod_rel)) ON COMMIT DROP;


-- 1. Originales
SELECT t.cod_ocupacion, t.nombre_ocupacion, t.cod_rel, t.nombre_rel
FROM   tmp_rel_cno t
JOIN   clasificacion.cno_ocupacion o ON o.cod_ocupacion_cno = t.cod_ocupacion
WHERE  NOT EXISTS (
         SELECT 1 FROM clasificacion.cno_relacionadas r
         WHERE  r.cod_ocupacion_cno = t.cod_ocupacion AND r.codigo_ocupacion = t.cod_rel
       );

-- 2. Copias existentes: heredan de su ocupación base
SELECT copia.cod_ocupacion_cno, t.nombre_ocupacion, t.cod_rel, t.nombre_rel
FROM   clasificacion.cno_ocupacion copia
JOIN   tmp_rel_cno t ON t.cod_ocupacion = regexp_replace(copia.cod_ocupacion_cno, '-[0-9]+(-[0-9]+)?$', '')
WHERE  copia.id_comparativa IS NOT NULL
  AND  NOT EXISTS (
         SELECT 1 FROM clasificacion.cno_relacionadas r
         WHERE  r.cod_ocupacion_cno = copia.cod_ocupacion_cno AND r.codigo_ocupacion = t.cod_rel
       );
